++    batch.extend_seq_lens = torch.tensor([2], dtype=torch.int32)
++    batch.extend_prefix_lens = torch.tensor([0], dtype=torch.int32)
++    batch.rids = ["request-0"]
++    batch.forward_mode = "extend"
++    return batch
